// Degree-16 Horner polynomial, mod 2^16, FULLY PIPELINED (one register per
// stage, with the input delayed alongside) -> short per-stage register stage
// chain (low register-to-register latency) + one multiply per stage
// (instruction-level parallelism) -> roughly linear latency提升函数 of the
// register-to-register latency.
module poly16_v13_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
