    reg  [15:0] r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15;
    reg  [15:0] y2;
    always @(*) r0 = 16'd45;
    always @(*) r1 = r0 * x + 16'd67;
    always @(*) r2 = r1 * x + 16'd56;
    always @(*) r3 = r2 * x + 16'd54;
    always @(*) r4 = r3 * x + 16'd26;
    always @(*) r5 = r4 * x + 16'd74;
    always @(*) r6 = r5 * x + 16'd47;
    always @(*) r7 = r6 * x + 16'd10;
    always @(*) r8 = r7 * x + 16'd96;
    always @(*) r9 = r8 * x + 16'd73;
    always @(*) r10 = r9 * x + 16'd22;
    always @(*) r11 = r10 * x + 16'd53;
    always @(*) r12 = r11 * x + 16'd23;
    always @(*) r13 = r12 * x + 16'd53;
    always @(*) r14 = r13 * x + 16'd77;
    always @(*) r15 = r14 * x + 16'd32;
    always @(*) y2 = r15 * x + 16'd61;
    always @(posedge clk) begin
